// Notify once per contract that entered a signature stage.
// Dedup by contract Id in workflow static data (survives runs).
const sd = $getWorkflowStaticData('global');
sd.notified = sd.notified || [];
const seen = new Set(sd.notified);

const res = $input.first() ? $input.first().json : {};
const records = (res && res.records) ? res.records : [];

const out = [];
for (const r of records) {
  if (!r || !r.Id) continue;
  if (seen.has(r.Id)) continue;            // already notified this contract
  seen.add(r.Id);
  const acct = (r.Account__r && r.Account__r.Name) ? r.Account__r.Name : '(unknown account)';
  const opp  = (r.Opportunity__r && r.Opportunity__r.Name) ? r.Opportunity__r.Name : '—';
  const tid  = r.SpotDraft_ID__c || '(no T-id)';
  const link = r.Contract_Link__c || '';
  const text =
    `:pencil: *Contract sent for signature* — *${acct}*\n` +
    `> *Status:* ${r.Status__c}\n` +
    `> *Contract:* ${tid}` + (link ? ` (<${link}|open in SpotDraft>)` : '') + `\n` +
    `> *Opportunity:* ${opp}`;
  out.push({ json: { channel: 'C0B88KMFJ3E', text } });
}

// keep the dedup list bounded
sd.notified = Array.from(seen).slice(-5000);
return out;
